def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    EPISODE_DAYS = 10 

    current_day = day_context['day']
    current_supply = day_context['supply']

    alive_opponents = [o for o in opponents_status.values() if o['alive']]
    num_alive_players = len(alive_opponents) + 1 

    if not alive_opponents:
        return min(my_status['budget'], DAILY_SALARY * 0.1)

    yesterday_bids = []
    for opp in alive_opponents:
        prev_trace = opp.get('previous_trace', {})
        if prev_trace and prev_trace.get('bid') is not None:
            yesterday_bids.append(prev_trace['bid'])

    base_bid = DAILY_SALARY * 0.75 

    if my_status['hp'] <= 3:
        base_bid = DAILY_SALARY * 1.1 
    elif my_status['hp'] <= 5:
        base_bid = DAILY_SALARY * 0.95 

    if yesterday_bids:
        highest_prev_bid = max(yesterday_bids)
        if highest_prev_bid > base_bid:
            base_bid = highest_prev_bid + 1.0 
        else:
            base_bid = max(base_bid, highest_prev_bid * 1.05) 

    total_water_needed_by_players = num_alive_players * WATER_REQ
    if current_supply < total_water_needed_by_players:
        scarcity_factor = 1.0 + (total_water_needed_by_players - current_supply) / total_water_needed_by_players
        base_bid *= scarcity_factor 

    if current_day >= EPISODE_DAYS * 0.7:
        base_bid *= 1.1 

    final_bid = min(my_status['budget'], max(1.0, base_bid))

    if my_status['budget'] < DAILY_SALARY and my_status['hp'] <= 2:
        final_bid = my_status['budget']

    return final_bid

