def get_bid(day_context, my_status, opponents_status):
    DAILY_SALARY = 140
    WATER_REQ = 8
    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']

    alive_opponents = [o for o in opponents_status.values() if o['alive']]

    # Extract previous day's bids from opponents
    prev_bids = []
    for opp in alive_opponents:
        trace = opp.get('previous_trace', {})
        if trace and trace.get('bid') is not None:
            prev_bids.append(trace['bid'])

    # Determine base bid factor based on our HP
    if hp <= 2:
        base_factor = 0.95
    elif hp <= 4:
        base_factor = 0.85
    elif hp <= 6:
        base_factor = 0.75
    else:
        base_factor = 0.65

    # Adjust based on supply tightness
    supply_ratio = supply / 25.0
    if supply_ratio < 0.6:
        base_factor += 0.2
    elif supply_ratio < 0.8:
        base_factor += 0.1

    # Adjust based on opponents' previous high bids
    if prev_bids:
        max_prev = max(prev_bids)
        # If opponents are bidding high, we may need to match
        if max_prev > DAILY_SALARY * 0.9:
            base_factor = max(base_factor, 0.9)
        # If we are desperate, outbid slightly
        if hp <= 3:
            base_factor = max(base_factor, max_prev / DAILY_SALARY + 0.05)

    # Compute bid
    bid = min(budget, DAILY_SALARY * base_factor)
    # Ensure we at least bid something if we need water badly
    if hp <= 1 and bid < 1:
        bid = min(budget, DAILY_SALARY * 0.5)
    # Round to 2 decimals
    return round(bid, 2)
